progressiveHints:
name = input("What is your name? ")
print("Welcome, " + name + "! The adventure begins.")

path = input("Forest or castle? ")

if path == "forest":
    print("You enter the dark forest.")
    animal = input("A creature blocks your path. Do you talk to it or run? ")
    if animal == "talk":
        print("It was a friendly wizard fox! You get a magic bean.")
    else:
        print("You run — but drop your snacks. The fox eats them.")
else:
    print("The castle gates open with a creak.")
    print("A ghost butler bows. 'Welcome, ' + name + '.'")

# Full example:
name = input("What is your name, hero? ")
print("Greetings, " + name + "! The kingdom needs your help.")

quest = input("Do you seek the lost crown or the stolen recipe? ")

if quest == "crown":
    print("You ride north to the Ice Mountains.")
    bridge = input("A rickety bridge blocks your path. Cross it or find another way? ")
    if bridge == "cross":
        print("You make it across! A snow fox cheers.")
        print("You find the crown and return a hero!")
    else:
        print("You find a secret tunnel — and a map to buried treasure too!")
else:
    print("You head to the Enchanted Bakery.")
    clue = input("The ghost chef offers a hint. Take it or guess yourself? ")
    if clue == "take it":
        print("The secret ingredient was moonlight! You save the bakery.")
    else:
        print("Your guess was 'dragon pepper' — the pastries explode (deliciously).")

print("\nTHE END. Well done, " + name + "!")
